 const [session,setSession]=useState<Session|null>(null),[loading,setLoading]=useState(true),[section,setSection]=useState('Resumen'),[modal,setModal]=useState<M>(null),[notice,setNotice]=useState(''),[selected,setSelected]=useState<R|null>(null),[undoTest,setUndoTest]=useState<R|null>(null),[q,setQ]=useState('');
