 {section==='Ensayos'&&<Tests rows={find(d.tests,q)} sampleMap={sampleMap} staffMap={staffMap} eqMap={eqMap} raw={d.raw} act={async(k:string,t:R)=>{await action(k,t,flash);refresh()}} open={()=>setModal('test')} rawOpen={(t:R)=>{setSelected(t);setModal('raw')}} admin={isAdmin} edit={(t:R)=>{setSelected(t);setModal('editTest')}} remove={async(t:R)=>{const reason=prompt('Motivo de eliminación del ensayo');if(reason===null)return;const {error}=await supabase.rpc('archive_test',{p_test_id:t.id,p_reason:reason});flash(error?error.message:'Ensayo eliminado con trazabilidad');if(!error){setUndoTest(t);refresh()}}}/>} 
