 {modal==='option'&&<Insert title="Nueva opción" table="app_options" fields={[['category','Grupo','optionCategory'],['value','Valor interno'],['label','Texto visible'],['sort_order','Orden','number'],['active','Activa','select:true|false']]} transform={(o:R)=>({...o,sort_order:Number(o.sort_order||100),active:o.active!=='false'})} close={()=>setModal(null)} done={()=>{setModal(null);refresh();flash('Opción creada')}}/>}{modal==='editOption'&&selected&&<Update title="Editar opción" table="app_options" row={selected} fields={[['category','Grupo','optionCategory'],['value','Valor interno'],['label','Texto visible'],['sort_order','Orden','number'],['active','Activa','select:true|false']]} opts={{options:d.options}} transform={(o:R)=>({...o,sort_order:Number(o.sort_order||100),active:o.active==='true'})} close={()=>{setModal(null);setSelected(null)}} done={()=>{setModal(null);setSelected(null);refresh();flash('Opción actualizada')}}/>}
