function Brand(){return <div className="brand"><img src={ASSET_BASE+'isotipo-segod.jpg'} alt="Isotipo SEGOD"/><div><strong>SEGOD</strong><small>Laboratorio</small></div><input className="mobile-nav-toggle" id="mobile-nav-toggle" type="checkbox" aria-label="Abrir o cerrar menú"/><label className="mobile-nav-button" htmlFor="mobile-nav-toggle" title="Menú"><span/><span/><span/></label></div>}
function Login(){const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[msg,setMsg]=useState(''),[busy,setBusy]=useState(false),[recover,setRecover]=useState(false);async function submit(e:FormEvent){e.preventDefault();setBusy(true);const login=email.trim().includes('@')?email.trim():email.trim()+'@segod.com.ar';const {error}=recover?await supabase.auth.resetPasswordForEmail(login,{redirectTo:new URL('.',location.href).href}):await supabase.auth.signInWithPassword({email:login,password});setMsg(error?'Usuario o contraseña incorrectos.':recover?'Te enviamos un enlace para cambiar la contraseña.':'');setBusy(false)}return <main className="login"><section><Brand/><div><p>CONTROL TÉCNICO</p><h1>Resultados trazables.<br/>Datos siempre disponibles.</h1><span>Gestión integral de muestras, ensayos, revisión, equipos y documentos.</span></div></section><form onSubmit={submit}><p>ACCESO INTERNO</p><h2>{recover?'Recuperar contraseña':'Ingresar al laboratorio'}</h2><label>Usuario o correo<input type="text" autoComplete="username" placeholder="matias.guarnera" value={email} onChange={e=>setEmail(e.target.value)} required/></label>{!recover&&<label>Contraseña<input type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} required/></label>}{msg&&<b className={msg.startsWith('Te')?'success':'error'}>{msg}</b>}<button className="primary" disabled={busy}>{busy?'Procesando…':recover?'Enviar enlace':'Ingresar'}</button><button type="button" className="text-button" onClick={()=>setRecover(!recover)}>{recover?'Volver':'Olvidé mi contraseña'}</button></form></main>}
function H({eyebrow='GESTIÓN',title}:{eyebrow?:string;title:string}){return <div><p>{eyebrow}</p><h2>{title}</h2></div>}function Badge({x}:{x:string}){return <span className={'badge '+slug(x)}>{x}</span>}function Title({x,action,go}:{x:string;action?:string;go?:()=>void}){return <div className="panel-head"><H title={x}/>{action&&<button className="primary" onClick={go}>{action}</button>}</div>}
function ListControls({sort,setSort,status,setStatus,options,statuses,statusLabel='Estado'}:{sort:string;setSort:(x:string)=>void;status:string;setStatus:(x:string)=>void;options:string[][];statuses:string[];statusLabel?:string}){return <div className="list-controls"><label>Ordenar<select value={sort} onChange={e=>setSort(e.target.value)}>{options.map(x=><option value={x[0]} key={x[0]}>{x[1]}</option>)}</select></label><label>{statusLabel}<select value={status} onChange={e=>setStatus(e.target.value)}><option value="">Todos</option>{statuses.map(x=><option key={x}>{x==='__active__'?'Activos (sin aprobados)':x}</option>)}</select></label></div>}
function Dashboard({d,open,backup}:{d:R;open:(x:M)=>void;backup:()=>void}){const today=new Date().toISOString().slice(0,10),soon=new Date(Date.now()+30*864e5).toISOString().slice(0,10),m=[['Muestras abiertas',d.samples.filter((x:R)=>!['Finalizada','Anulada'].includes(x.status)).length],['Ingresadas hoy',d.samples.filter((x:R)=>x.received_at===today).length],['Ensayos pendientes',d.tests.filter((x:R)=>x.status==='Pendiente').length],['En ejecución',d.tests.filter((x:R)=>['Ejecutado','Datos Cargados'].includes(x.status)).length],['Pendientes de revisión',d.tests.filter((x:R)=>x.status==='Pendiente de revisión').length],['Observados',d.tests.filter((x:R)=>x.status==='Observado').length],['Equipos vencidos',d.equipment.filter((x:R)=>x.expires_at&&x.expires_at<today).length],['Próximos a vencer',d.equipment.filter((x:R)=>x.expires_at>=today&&x.expires_at<=soon).length]];return <><div className="metrics metrics-4">{m.map(x=><article key={x[0]}><span>{x[0]}</span><strong>{x[1]}</strong></article>)}</div><div className="content-grid"><article className="panel"><H eyebrow="TRABAJO PENDIENTE" title="Ensayos activos"/><div className="rows">{d.tests.filter((x:R)=>!['Aprobado','Anulado','No Ensayado','N/A'].includes(x.status)).slice(0,8).map((t:R)=><div className="row" key={t.id}><div><strong>{t.test_name}</strong><small>Repetición {t.repetition_no}</small></div><Badge x={t.status}/></div>)}</div></article><aside className="panel quick"><H title="Accesos rápidos"/><button onClick={()=>open('sample')}>Ingresar muestra <span>→</span></button><button onClick={()=>open('raw')}>Cargar datos <span>→</span></button><button onClick={()=>open('event')}>Evento de equipo <span>→</span></button><button onClick={backup}>Backup completo <span>↓</span></button></aside></div></>}
function Samples({rows,choose,open,bulk}:{rows:R[];choose:(x:R)=>void;open:()=>void;bulk:(ids:string[],kind:string,notes:string)=>Promise<void>}){const [sort,setSort]=useState('received_at:desc'),[status,setStatus]=useState(''),[selected,setSelected]=useState<string[]>([]),[bulkKind,setBulkKind]=useState(''),[busy,setBusy]=useState(false);const view=sortRows(rows.filter(x=>!status||x.status===status),sort),toggle=(id:string)=>setSelected(x=>x.includes(id)?x.filter(v=>v!==id):[...x,id]);async function apply(){if(!selected.length||!bulkKind)return;const labels:R={review:'Enviar a revisión',approve:'Aprobar',observe:'Marcar observado',not_tested:'Marcar No Ensayado'};const notes=bulkKind==='observe'?prompt('Observación para todos los ensayos seleccionados')??'':bulkKind==='not_tested'?prompt('Motivo para marcar como No Ensayado')??'':'';if((bulkKind==='observe'||bulkKind==='not_tested')&&!notes)return;if(!confirm(`${labels[bulkKind]} los ensayos aplicables de ${selected.length} muestra(s)?`))return;setBusy(true);await bulk(selected,bulkKind,notes);setBusy(false);setSelected([]);setBulkKind('')}return <article className="panel table-panel"><Title x="Muestras y órdenes" action="Nueva muestra" go={open}/><ListControls sort={sort} setSort={setSort} status={status} setStatus={setStatus} options={[['received_at:desc','Ingreso: más recientes'],['received_at:asc','Ingreso: más antiguas'],['display_name:asc','Nombre de muestra'],['sample_name:asc','ID interno'],['product:asc','Material A–Z'],['requester:asc','Solicitante A–Z']]} statuses={[...new Set(rows.map(x=>x.status).filter(Boolean))]}/><div className="bulk-toolbar"><label><input type="checkbox" checked={view.length>0&&view.every(s=>selected.includes(s.id))} onChange={e=>setSelected(e.target.checked?[...new Set([...selected,...view.map(s=>s.id)])]:selected.filter(id=>!view.some(s=>s.id===id)))}/> Seleccionar las visibles</label><strong>{selected.length} muestra(s) seleccionada(s)</strong><select value={bulkKind} onChange={e=>setBulkKind(e.target.value)}><option value="">Acción en lote…</option><option value="review">Enviar a revisión</option><option value="approve">Aprobar</option><option value="observe">Marcar observado</option><option value="not_tested">Marcar No Ensayado</option></select><button className="primary" disabled={!selected.length||!bulkKind||busy} onClick={apply}>{busy?'Aplicando…':'Aplicar'}</button></div><p className="bulk-help">La acción se aplica únicamente a los ensayos vigentes y compatibles de cada muestra seleccionada.</p><div className="table six"><div className="tr th"><span>Muestra / ID</span><span>Ingreso</span><span>Material</span><span>Lote / OP</span><span>Ensayos</span><span>Estado</span></div>{view.map(s=><div className="tr clickable sample-row" key={s.id} onClick={()=>choose(s)}><span className="sample-name"><input aria-label={'Seleccionar '+sampleTitle(s)} type="checkbox" checked={selected.includes(s.id)} onClick={e=>e.stopPropagation()} onChange={()=>toggle(s.id)}/><span><strong>{sampleTitle(s)}</strong><small>{s.sample_name}</small></span></span><span>{s.received_at}</span><span>{s.product}</span><span>{[s.lot,s.batch,s.work_order].filter(isApplicable).join(' · ')||'—'}</span><span>{s.requested_tests_list?.join(', ')||'—'}</span><Badge x={s.status}/></div>)}</div></article>}
function SampleDetail({s,tests,raw,staffMap,eqMap,back,act,report,manage,admin,edit,editTest,removeTest,remove}:{s:R;tests:R[];raw:R[];staffMap:R;eqMap:R;back:()=>void;act:(k:string,t:R)=>void;report:()=>void;manage:boolean;admin:boolean;edit:()=>void;editTest:(t:R)=>void;removeTest:(t:R)=>void;remove:()=>void}){const [showApproved,setShowApproved]=useState(false),visibleTests=tests.filter(t=>showApproved||t.status!=='Aprobado');return <><div className="detail-head"><button className="secondary" onClick={back}>← Volver</button><div><h2>{sampleTitle(s)}</h2><p>ID interno {s.sample_name} · {s.requester||'Sin solicitante'} · {s.received_at}</p></div><div className="detail-actions"><button className="primary" onClick={report}>Descargar PDF</button>{manage&&<><button className="secondary" onClick={edit}>Editar muestra</button><button className="danger-button" onClick={remove}>Eliminar muestra</button></>}</div></div><div className="detail-grid"><article className="panel"><H eyebrow="RECEPCIÓN" title="Datos de la muestra"/><dl className="facts">{[['Material',s.product],['Modelo',s.model],['Talle / Mano',[s.size,s.hand].filter(isApplicable).join(' · ')],['Lote / Partida / OP',[s.lot,s.batch,s.work_order].filter(isApplicable).join(' · ')],['Cantidad',s.quantity_received],['Conservación',s.conservation_conditions],['Estado',s.status],['Observaciones',s.notes]].map(x=><span key={x[0]}><dt>{x[0]}</dt><dd>{x[1]||'—'}</dd></span>)}</dl></article><article className="panel"><Title x="Ejecuciones" action={showApproved?'Ocultar aprobados':'Ver aprobados'} go={()=>setShowApproved(!showApproved)}/><div className="cards">{visibleTests.map(t=><TestCard key={t.id} t={t} sample={s} raw={raw} staffMap={staffMap} eqMap={eqMap} act={act} admin={admin} edit={()=>editTest(t)} remove={()=>removeTest(t)}/>)}</div>{!visibleTests.length&&<p className="empty-note">No hay ensayos activos para mostrar.</p>}</article></div></>}
