function Raw({rows,tests,sampleMap,eqMap,open,backup}:{rows:R[];tests:R[];sampleMap:R;eqMap:R;open:()=>void;backup:()=>void}){const tm=Object.fromEntries(tests.map(x=>[x.id,x])),sampleIds=[...new Set(rows.map(x=>x.sample_id))];return <article className="panel table-panel"><Title x="Datos crudos trazables" action="Agregar registro" go={open}/><button className="secondary backup-inline" onClick={backup}>Exportar backup</button><div className="raw-groups">{sampleIds.map(sampleId=>{const s=sampleMap[sampleId],sampleRows=rows.filter(x=>x.sample_id===sampleId),testIds=[...new Set(sampleRows.map(x=>x.sample_test_id))];return <section className="raw-sample-group" key={sampleId}><header><div><h3>{sampleTitle(s)}</h3><p>{sampleIdentity(s).join(' · ')}</p></div><Badge x={sampleRows.length+' registros'}/></header>{testIds.map(testId=><div className="raw-test-group" key={testId}><h4>{tm[testId]?.test_name||'Ensayo'}</h4><div className="raw-cards">{sampleRows.filter(x=>x.sample_test_id===testId).map(r=><div className="raw-card" key={r.id}><header><strong>{LABEL[r.data_type]||r.data_type}</strong><Badge x={r.voided?'Anulado':r.status}/></header><pre>{JSON.stringify(r.raw_values,null,2)}</pre><small>{r.calculated_result??'—'} {r.units||''} · {r.compliance||'No evaluado'}</small><small>Equipo: {eqMap[r.equipment_id]||'—'} ({r.equipment_status||'sin estado'})</small></div>)}</div></div>)}</section>})}</div></article>}
