function People({staff,training,open}:{staff:R[];training:R[];open:()=>void}){const [people,setPeople]=useState(staff),[editing,setEditing]=useState<R|null>(null),[creating,setCreating]=useState(false),[admin,setAdmin]=useState(false);useEffect(()=>setPeople(staff),[staff]);useEffect(()=>{let live=true;supabase.auth.getUser().then(({data})=>{const p=staff.find(x=>x.email?.toLowerCase()===data.user?.email?.toLowerCase());if(live)setAdmin(!!p?.can_manage_records)});return()=>{live=false}},[staff]);async function refresh(){const {data}=await supabase.from('staff').select('*').order('full_name');if(data)setPeople(data)}async function deactivate(p:R){if(!confirm(`¿Dar de baja a ${p.full_name}? Se conservará su historial.`))return;const {error}=await supabase.from('staff').update({status:'Inactivo',inactivated_at:new Date().toISOString().slice(0,10)}).eq('id',p.id);if(error)alert(error.message);else refresh()}return <div className="stack"><article className="panel"><Title x="Personal y permisos" action={admin?'Agregar personal':undefined} go={admin?()=>setCreating(true):undefined}/><p className="people-help">Las bajas son lógicas: el historial de muestras y ensayos se conserva.</p><div className="people-grid">{people.map(p=><div className={'person '+(p.status==='Inactivo'?'person-inactive':'')} key={p.id}><header><strong>{p.full_name}</strong><Badge x={p.status||'Activo'}/></header><span>{p.role||p.job_title||'Sin rol'}</span><small>{p.email||'Sin correo'}</small><p>{p.can_run_tests?'Ejecuta': 'No ejecuta'} · {p.can_review?'Revisa':'No revisa'} · {p.can_approve_reports?'Aprueba':'No aprueba'}</p><small>{p.status==='Inactivo'?'Inactivación': 'Activación'}: {p.status==='Inactivo'?p.inactivated_at:p.activated_at||'Sin registrar'}</small><small>{p.authorized_tests||'Sin autorizaciones'}</small>{admin&&<footer><button className="edit-inline" onClick={()=>setEditing(p)}>Editar</button>{p.status!=='Inactivo'&&<button className="danger-button" onClick={()=>deactivate(p)}>Dar de baja</button>}</footer>}</div>)}</div></article><article className="panel"><Title x="Capacitaciones" action="Registrar" go={open}/><Table cols={[['Persona','staff_id'],['Tema','topic'],['Fecha','trained_at'],['Vencimiento','expires_at'],['Resultado','result']]} rows={training.map(x=>({...x,staff_id:people.find(s=>s.id===x.staff_id)?.full_name}))}/></article>{creating&&<StaffForm close={()=>setCreating(false)} done={()=>{setCreating(false);refresh()}}/>}{editing&&<StaffForm row={editing} close={()=>setEditing(null)} done={()=>{setEditing(null);refresh()}}/>}</div>}
