function Table({cols,rows}:{cols:string[][];rows:R[]}){return <div className="simple-table"><div className="simple-row head">{cols.map(x=><span key={x[1]}>{x[0]}</span>)}</div>{rows.map((r,i)=><div className="simple-row" key={r.id||i}>{cols.map(x=><span key={x[1]}>{fmt(r[x[1]])}</span>)}</div>)}</div>}
function Account({email,flash}:{email:string;flash:(x:string)=>void}){const [error,setError]=useState(''),[busy,setBusy]=useState(false);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget,f=new FormData(form),current=String(f.get('current')),p=String(f.get('password')),c=String(f.get('confirm'));setError('');if(p.length<8)return setError('Mínimo 8 caracteres');if(p!==c)return setError('Las contraseñas no coinciden');setBusy(true);const verified=await supabase.auth.signInWithPassword({email,password:current});if(verified.error){setBusy(false);return setError('La contraseña actual no es correcta')}const {error}=await supabase.auth.updateUser({password:p});setBusy(false);if(error)setError(error.message);else{form.reset();flash('Contraseña actualizada')}}return <article className="panel account-panel"><H eyebrow="SEGURIDAD" title="Mi cuenta"/><p className="body">Sesión iniciada como <strong>{email}</strong>. Por seguridad, confirmá tu contraseña actual.</p><form className="password-form" onSubmit={submit}><label>Contraseña actual<input name="current" type="password" autoComplete="current-password" required/></label><label>Nueva contraseña<input name="password" type="password" minLength={8} autoComplete="new-password" required/></label><label>Repetir contraseña<input name="confirm" type="password" minLength={8} autoComplete="new-password" required/></label>{error&&<b className="error">{error}</b>}<button className="primary" disabled={busy}>{busy?'Verificando…':'Cambiar contraseña'}</button></form></article>}

async function action(k:string,t:R,flash:(x:string)=>void){let error:any;if(k==='repeat'){const r=prompt('Motivo de la repetición');if(!r)return;({error}=await supabase.rpc('repeat_test',{p_test_id:t.id,p_reason:r}))}if(k==='review')({error}=await supabase.rpc('send_test_to_review',{p_test_id:t.id}));if(k==='approve')({error}=await supabase.rpc('review_test',{p_test_id:t.id,p_decision:'Aprobado',p_notes:'Resultado conforme'}));if(k==='observe'){const n=prompt('Observación técnica');if(!n)return;({error}=await supabase.rpc('review_test',{p_test_id:t.id,p_decision:'Observado',p_notes:n}))}flash(error?error.message:'Acción registrada')}
function calculate(type:string,v:R,unit:string){const n=(...ks:string[])=>ks.map(k=>v[k]).filter(x=>typeof x==='number'&&Number.isFinite(x)) as number[],avg=(a:number[])=>a.length?a.reduce((x,y)=>x+y,0)/a.length:null,level=(x:number|null,t:number[])=>x==null?null:t.reduce((r,z,i)=>x>=z?i+1:r,0),out=(result:number|null,units:string,classification:string|null,compliance='No evaluado',derived:R={})=>({result,units,classification,compliance,derived}),na=(units=unit)=>out(null,units,'No aplicable','N/A');if(type==='marcado'){const a=Object.values(v).map(x=>String(x).toLowerCase()).filter(x=>x!=='n/a'),bad=a.some(x=>x==='no cumple'),pending=a.some(x=>x==='no evaluado');return a.length?out(null,'',bad?'No conforme':pending?'Evaluación incompleta':'Conforme',bad?'No cumple':pending?'No evaluado':'Cumple'):na('')}if(type==='desteridad'){const x=n('diametro','varilla')[0]??null;if(x==null)return na('mm');const lv=x<=5?5:x<=6.5?4:x<=8?3:x<=9.5?2:x<=11?1:0;return out(x,'mm','Nivel '+lv,lv?'Cumple':'No cumple')}if(type==='cromo_vi'){const x=n('medicion')[0]??null,below=String(v['debajo-del-limite']||'').toLowerCase();if(x==null&&!['si','sí','no'].includes(below))return na(unit||'mg/kg');const ok=below==='si'||below==='sí'||(x!=null&&x<=3);return out(x,unit||'mg/kg',ok?'≤3 mg/kg':'>3 mg/kg',ok?'Cumple':'No cumple')}if(type==='ph'){const x=n('ph-medido')[0]??null,d=n('ph-dilucion')[0]??null;if(x==null)return na('pH');const difference=d==null?null:Math.abs(x-d),inRange=x>=3.5&&x<=9.5,lowWithValidDifference=x<3.5&&difference!=null&&difference<=0.5,ok=inRange||lowWithValidDifference,classification=inRange?'Intervalo 3,5–9,5':x<3.5?(difference==null?'Índice de diferencia pendiente':difference<=0.5?'Índice de diferencia ≤ 0,5':'Índice de diferencia > 0,5'):'Fuera de intervalo';return out(x,'pH',classification,ok?'Cumple':difference==null&&x<3.5?'No evaluado':'No cumple',{indice_de_diferencia:difference})}if(type==='corte_cuchilla'){const idx:number[]=[];for(let i=1;i<=5;i++){const a=n('c'+i,'c'+(i+1),'t'+i);if(a.length===3&&a[0]+a[1]>0){const z=2*a[2]/(a[0]+a[1]);idx.push(z);v['i'+i]=Number(z.toFixed(3))}}const r=avg(idx);if(r==null)return na(unit||'Índice');const lv=level(r,[1.2,2.5,5,10,20]);return out(r,unit||'Índice','Nivel '+(lv??0),(lv??0)>0?'Cumple':'No cumple',{indices:idx})}if(type==='abrasion'){const a=n('probeta-1','probeta-2','probeta-3','probeta-4','ciclos'),r=a.length?Math.min(...a):null;if(r==null)return na(unit||'ciclos');const lv=level(r,[100,500,2000,8000]);return out(r,unit||'ciclos','Nivel '+(lv??0),(lv??0)>0?'Cumple':'No cumple')}if(type==='rasgado'){const r=avg(n('probeta-1','probeta-2','probeta-3','probeta-4'));if(r==null)return na(unit||'N');const lv=level(r,[10,25,50,75]);return out(r,unit||'N','Nivel '+(lv??0),(lv??0)>0?'Cumple':'No cumple')}if(type==='perforacion'){const a=n('probeta-1','probeta-2','probeta-3','probeta-4'),r=a.length?Math.min(...a):null;if(r==null)return na(unit||'N');const lv=level(r,[20,60,100,150]);return out(r,unit||'N','Nivel '+(lv??0),(lv??0)>0?'Cumple':'No cumple')}if(type==='impacto'){const a=n(...Array.from({length:10},(_,i)=>'m'+(i+1))),r=avg(a);if(r==null)return na(unit||'kN');const mx=Math.max(...a),ok=r<=7&&mx<=9;return out(r,unit||'kN',ok?'P':'Sin nivel P',ok?'Cumple':'No cumple',{maximo:mx})}const r=avg(Object.values(v).filter(x=>typeof x==='number'&&Number.isFinite(x)) as number[]);return r==null?na(unit):out(r,unit,'Resultado calculado')}
async function backup(flash:(x:string)=>void){const names=['staff','staff_training','test_catalog','equipment','equipment_events','documents','samples','sample_tests','raw_test_data','audit_log','lab_alerts'],out:R={exported_at:new Date().toISOString(),format_version:2};for(const n of names){const {data,error}=await supabase.from(n).select('*');if(error)return flash('No se pudo exportar '+n);out[n]=data}download('segod-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(out,null,2),'application/json');flash('Backup descargado')}
function reportFileName(s:R){const name=sampleTitle(s).replace(/[<>:"/\\|?*]/g,'-').replace(/\s+/g,' ').trim()||'Muestra';const date=String(s.received_at||'').replace(/\D/g,'').slice(0,8)||'SinFecha';return `QF-04 ${name} ${date}.pdf`}
function reportQrSummary(s:R,tests:R[],raw:R[],staff:R,eq:R){const sample=[s.internal_id||s.sample_name||s.id,s.received_at,s.requester,s.product,s.lot,s.batch,s.model,s.size,s.requested_standard,s.quantity_received,s.status];const ensayo=tests.map(t=>[t.test_name,t.applied_standard||'Método interno',[t.final_result,t.units].filter(Boolean).join(' '),t.classification,t.compliance,t.status,staff[t.assigned_to]||'Gonzalo Torti',eq[t.equipment_id]||null]);return JSON.stringify({d:'QF-04',k:['id','recep','sol','mat','lote','part','modelo','talle','norma','cant','estado'],m:sample,t:ensayo,raw:raw.filter(x=>x.sample_id===s.id&&!x.voided).length})}
async function downloadReport(s:R,tests:R[],raw:R[],staff:R,eq:R){downloadBlob(reportFileName(s),await reportPdf(s,tests,raw,staff,eq))}
async function reportPdf(s:R,tests:R[],raw:R[],staff:R,eq:R){const st=tests.filter(x=>x.sample_id===s.id);return appendQrPage(makeBetterLabReportPdf(s,st,raw,staff,eq),reportQrSummary(s,st,raw,staff,eq))}
